import React from "react";

function About() {
  return (
    <div className="container">
      <h2>About FoodCycle</h2>
      <p>FoodCycle is a platform dedicated to reducing food waste by connecting people who have surplus food with those who need it.</p>
      <p>Our mission is to create a sustainable community where no food goes to waste, and everyone has access to nutritious meals.</p>
      <ul>
        <li>Donate excess food to help others</li>
        <li>Buy affordable food from local sellers</li>
        <li>Track food locations on our interactive map</li>
      </ul>
    </div>
  );
}

export default About;
